function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const top = rand() < 0.5 ? 1000000000 : pick(1, 1000);
    const nums = Array.from({ length: n }, () => pick(1, top));
    return [nums, pick(1, 100000)];
  }
  const n = pick(1, 8);
  const top = rand() < 0.6 ? pick(1, 40) : 1000000000;
  const nums = Array.from({ length: n }, () => pick(1, top));
  return [nums, pick(1, 14)];
}
